mapper.select:
SELECT * FROM ( SELECT e.equipment_id AS equipmentId, t.tenant_code AS tenantCode, e.equip_sys_cd AS equipSysCd, e.equip_cd AS equipCd, e.equip_nm AS equipNm, e.equip_kind AS equipKind, e.pur_date AS purDate, e.pur_cust AS purCust, e.mak_cust AS makCust, e.equip_spec AS equipSpec, e.location AS location, e.bigo AS bigo, CASE WHEN e.use_at = 'Y' THEN TRUE ELSE FALSE END AS active, ROW_NUMBER() OVER (ORDER BY e.equip_sys_cd) AS rn FROM tb_equipment_info e JOIN tb_tenant t ON t.tenant_id = e.tenant_id WHERE 1 = 1
AND t.tenant_code = #{tenantCode}
AND ( LOWER(COALESCE(e.equip_nm, '')) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(COALESCE(e.equip_kind, '')) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(COALESCE(e.pur_cust, '')) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(COALESCE(e.mak_cust, '')) LIKE '%' || LOWER(#{keyword}) || '%' OR e.equip_sys_cd LIKE '%' || #{keyword} || '%' OR e.equip_cd LIKE '%' || #{keyword} || '%' )
AND e.use_at = 'Y'
AND e.use_at = 'N'
) equipment_query WHERE rn BETWEEN #{firstIndex} AND #{lastIndex} ORDER BY rn

SELECT u.user_id
FROM tb_user u
JOIN tb_login_account la ON la.login_id = u.login_id
WHERE la.tenant_id = #{tenantId}
  AND la.login_code = #{loginCode}
LIMIT 1

SELECT MAX(equip_sys_cd)
FROM tb_equipment_info
WHERE tenant_id = #{value}

mapper.delete:
DELETE FROM tb_equipment_info
WHERE equipment_id = #{equipmentId}
  AND tenant_id    = #{tenantId}
